for id, p in (('i185_2', off(SCH, 80, 60)), ('b8_1', off(SCH, -120, 100)), ('b8_2', off(SCH, 150, -100)), ('i185_1', off(SCH, 40, 220))):
    go(id, A("22:01"), A("22:30"), p, state="line")
