    go(id, A(t0), plus(A(t0), 25), (POS[id][0] + 0.7 * (p[0] - POS[id][0]), POS[id][1] + 0.7 * (p[1] - POS[id][1])), strength=n + 60)
    at(id, plus(A(t0), 26), strength=n); dusk(id, DARK)
