go('mx2', ZERO, A("07:50"), beyond('mx2', 120), state="firing", strength=200); lose('mx2', A("09:00"), A("15:00"), 60); dusk('mx2', DARK)
stopped('devon2', ZERO, 0.75, 260, DARK)
