for id in ('koyli8', 'yl8'):
    go(id, ZERO, A("07:45"), Gp(id), state="firing", strength=520); go(id, A("07:46"), A("07:58"), beyond(id, 300), state="firing", strength=300)
    lose(id, A("08:30"), A("14:30"), 90); dusk(id, DARK)
