stopped('nf20', ZERO, 0.3, 190, DARK); stopped('nf23', ZERO, 0.35, 170, DARK)
for k, id in enumerate(('nf27', 'nf26', 'nf25', 'nf24')):
    go(id, ZERO, A("07:58"), back(on_line(BL, POS[id]), 30), strength=225)
